CREATE    VIEW [CE].[vwIncident]
AS

	SELECT 
		inc.[incidentid],
		inc.[statecode],
		inc.[statecode_description],
		inc.[statuscode],
		inc.[statuscode_description],
		inc.[caseorigincode],
		inc.[caseorigincode_description],
		inc.[casetypecode],
		inc.[casetypecode_description],
		inc.[firstresponseslastatus],
		inc.[incidentstagecode],
		inc.[prioritycode],
		inc.[resolvebyslastatus],
		inc.[servicestage],
		inc.[severitycode],
		inc.[activitiescomplete],
		inc.[adx_publishtoweb],
		inc.[masterid],
		inc.[masteridname],
		inc.[resolvebykpiid],
		inc.[resolvebykpiidname],
		inc.[subjectid],
		inc.[subjectidname],
		inc.[transactioncurrencyidname],
		inc.[owneridname],
		inc.[customerid],
		inc.[customeridname],
		inc.[caseage],
		inc.[createdbyname],
		inc.[createdon],
		inc.[deactivatedon],
		inc.[description],
		inc.[exchangerate],
		inc.[firstresponsebykpiidname],
		inc.[importsequencenumber],
		inc.[modifiedbyname],
		inc.[modifiedon],
		inc.[nextsla],
		inc.[owningbusinessunitname],
		inc.[ticketnumber],
		inc.[title],
		inc.[apuk_responsedueon],
		inc.[apuk_region],
		inc.[apuk_casereopencount],
		inc.[apuk_originatingdate],
		cnt.MemberGrade_Description AS [MemberGrade]
	FROM [synapse_ce].[vwIncident] inc
		LEFT JOIN synapse_ce.tblContact_BI cnt
			ON inc.[customerid] = cnt.[ContactId]
